952: func getRevision(tx backend.BatchTx) uint64 {
953: 	_, vs := tx.UnsafeRange(authBucketName, []byte(revisionKey), nil, 0)
954: 	if len(vs) != 1 {
955: 		// this can happen in the initialization phase
956: 		return 0
957: 	}
958: 
959: 	return binary.BigEndian.Uint64(vs[0])
960: }
961: 
962: func (as *authStore) setRevision(rev uint64) {
963: 	atomic.StoreUint64(&as.revision, rev)
964: }
965: 
966: func (as *authStore) Revision() uint64 {
967: 	return atomic.LoadUint64(&as.revision)
968: }
969: 
970: func (as *authStore) AuthInfoFromTLS(ctx context.Context) *AuthInfo {
971: 	peer, ok := peer.FromContext(ctx)
972: 	if !ok || peer == nil || peer.AuthInfo == nil {
973: 		return nil
974: 	}
975: 
976: 	tlsInfo := peer.AuthInfo.(credentials.TLSInfo)
977: 	for _, chains := range tlsInfo.State.VerifiedChains {
978: 		for _, chain := range chains {
979: 			cn := chain.Subject.CommonName
980: 			plog.Debugf("found common name %s", cn)
981: 
982: 			return &AuthInfo{
983: 				Username: cn,
984: 				Revision: as.Revision(),
985: 			}
986: 		}
987: 	}
988: 
989: 	return nil
990: }
991: 
992: func (as *authStore) AuthInfoFromCtx(ctx context.Context) (*AuthInfo, error) {
993: 	md, ok := metadata.FromIncomingContext(ctx)
994: 	if !ok {
995: 		return nil, nil
996: 	}
997: 
998: 	//TODO(mitake|hexfusion) review unifying key names
999: 	ts, ok := md["token"]
1000: 	if !ok {
1001: 		ts, ok = md["authorization"]
1002: 	}
1003: 	if !ok {
1004: 		return nil, nil
1005: 	}
1006: 
1007: 	token := ts[0]
1008: 	authInfo, uok := as.authInfoFromToken(ctx, token)
1009: 	if !uok {
1010: 		plog.Warningf("invalid auth token: %s", token)
1011: 		return nil, ErrInvalidAuthToken
1012: 	}
1013: 
1014: 	return authInfo, nil
1015: }
1016: 
1017: func (as *authStore) GenTokenPrefix() (string, error) {
1018: 	return as.tokenProvider.genTokenPrefix()
1019: }
1020: 
1021: "}

