14: 
15: package v3rpc
16: 
17: import (
18: 	"context"
19: 	"sync"
20: 	"time"
21: 
22: 	"github.com/coreos/etcd/etcdserver"
23: 	"github.com/coreos/etcd/etcdserver/api"
24: 	"github.com/coreos/etcd/etcdserver/api/v3rpc/rpctypes"
25: 	"github.com/coreos/etcd/pkg/types"
26: 	"github.com/coreos/etcd/raft"
27: 
28: 	prometheus "github.com/grpc-ecosystem/go-grpc-prometheus"
29: 	"google.golang.org/grpc"
30: 	"google.golang.org/grpc/metadata"
31: )
32: 
33: const (
34: 	maxNoLeaderCnt = 3
35: )
36: 
37: type streamsMap struct {
38: 	mu      sync.Mutex
39: 	streams map[grpc.ServerStream]struct{}
40: }
41: 
42: func newUnaryInterceptor(s *etcdserver.EtcdServer) grpc.UnaryServerInterceptor {
43: 	return func(ctx context.Context, req interface{}, info *grpc.UnaryServerInfo, handler grpc.UnaryHandler) (resp interface{}, err error) {
44: 		if !api.IsCapabilityEnabled(api.V3rpcCapability) {
45: 			return nil, rpctypes.ErrGRPCNotCapable
46: 		}
47: 
48: 		md, ok := metadata.FromIncomingContext(ctx)
49: 		if ok {
50: 			if ks := md[rpctypes.MetadataRequireLeaderKey]; len(ks) > 0 && ks[0] == rpctypes.MetadataHasLeader {
51: 				if s.Leader() == types.ID(raft.None) {
52: 					return nil, rpctypes.ErrGRPCNoLeader
53: 				}
54: 			}
55: 		}
56: 
57: 		return prometheus.UnaryServerInterceptor(ctx, req, info, handler)
58: 	}
59: }
60: 
61: func newStreamInterceptor(s *etcdserver.EtcdServer) grpc.StreamServerInterceptor {
62: 	smap := monitorLeader(s)
63: 
64: 	return func(srv interface{}, ss grpc.ServerStream, info *grpc.StreamServerInfo, handler grpc.StreamHandler) error {
65: 		if !api.IsCapabilityEnabled(api.V3rpcCapability) {
66: 			return rpctypes.ErrGRPCNotCapable
67: 		}
68: 
69: 		md, ok := metadata.FromIncomingContext(ss.Context())
70: 		if ok {
71: 			if ks := md[rpctypes.MetadataRequireLeaderKey]; len(ks) > 0 && ks[0] == rpctypes.MetadataHasLeader {
72: 				if s.Leader() == types.ID(raft.None) {
73: 					return rpctypes.ErrGRPCNoLeader
74: 				}
75: 
76: 				cctx, cancel := context.WithCancel(ss.Context())
77: 				ss = serverStreamWithCtx{ctx: cctx, cancel: &cancel, ServerStream: ss}
78: 
79: 				smap.mu.Lock()
80: 				smap.streams[ss] = struct{}{}
81: 				smap.mu.Unlock()
82: 
83: 				defer func() {
84: 					smap.mu.Lock()
85: 					delete(smap.streams, ss)
86: 					smap.mu.Unlock()
87: 					cancel()
88: 				}()
89: 
90: 			}
91: 		}
92: 
93: 		return prometheus.StreamServerInterceptor(srv, ss, info, handler)
94: 	}
95: }
96: 
97: type serverStreamWithCtx struct {
98: 	grpc.ServerStream
99: 	ctx    context.Context
100: 	cancel *context.CancelFunc
101: }
102: 
103: func (ssc serverStreamWithCtx) Context() context.Context { return ssc.ctx }
104: 
105: func monitorLeader(s *etcdserver.EtcdServer) *streamsMap {
106: 	smap := &streamsMap{
107: 		streams: make(map[grpc.ServerStream]struct{}),
108: 	}
109: 
110: 	go func() {
111: 		election := time.Duration(s.Cfg.TickMs) * time.Duration(s.Cfg.ElectionTicks) * time.Millisecond
112: 		noLeaderCnt := 0
113: 
114: 		for {
115: 			select {
116: 			case <-s.StopNotify():
117: 				return
118: 			case <-time.After(election):
119: 				if s.Leader() == types.ID(raft.None) {
120: 					noLeaderCnt++
121: 				} else {
122: 					noLeaderCnt = 0
123: 				}
124: 
125: 				// We are more conservative on canceling existing streams. Reconnecting streams
126: 				// cost much more than just rejecting new requests. So we wait until the member
127: 				// cannot find a leader for maxNoLeaderCnt election timeouts to cancel existing streams.
128: 				if noLeaderCnt >= maxNoLeaderCnt {
129: 					smap.mu.Lock()
130: 					for ss := range smap.streams {
131: 						if ssWithCtx, ok := ss.(serverStreamWithCtx); ok {
132: 							(*ssWithCtx.cancel)()
133: 							<-ss.Context().Done()
134: 						}
135: 					}
136: 					smap.streams = make(map[grpc.ServerStream]struct{})
137: 					smap.mu.Unlock()
138: 				}
139: 			}
140: 		}
141: 	}()
142: 
143: 	return smap
144: }
145: "}

