45: 			return nil, rpctypes.ErrGRPCNotCapable
46: 		}
47: 
48: 		md, ok := metadata.FromIncomingContext(ctx)
49: 		if ok {
50: 			if ks := md[rpctypes.MetadataRequireLeaderKey]; len(ks) > 0 && ks[0] == rpctypes.MetadataHasLeader {
