34: // LeaseGrantResponse wraps the protobuf message LeaseGrantResponse.
35: type LeaseGrantResponse struct {
36: 	*pb.ResponseHeader
37: 	ID    LeaseID
38: 	TTL   int64
39: 	Error string
40: }
