302: 		resp, err := l.keepAliveOnce(ctx, id)
303: 		if err == nil {
304: 			if resp.TTL <= 0 {
305: 				err = rpctypes.ErrLeaseNotFound
306: 			}
307: 			return resp, err
308: 		}
309: 		if isHaltErr(ctx, err) {
310: 			return nil, toErr(ctx, err)
