315: func (l *lessor) Close() error {
316: 	l.stopCancel()
317: 	// close for synchronous teardown if stream goroutines never launched
318: 	l.firstKeepAliveOnce.Do(func() { close(l.donec) })
319: 	<-l.donec
320: 	return nil
321: }
