322: 			}
323: 			ticker = time.After(time.Duration(rp.TTL) * time.Second)
324: 			r := &pb.LeaseKeepAliveResponse{
325: 				Header: rp.ResponseHeader,
326: 				ID:     int64(rp.ID),
327: 				TTL:    rp.TTL,
328: 			}
329: 			lps.replyToClient(r, neededResps)
330: 		}
331: 	}
332: }
